insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (1, 'Princeton University', '프린스턴 대학교', 1, 1, 1510, 1570, 'PLACEHOLDER', null, true, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (2, 'MIT', '매사추세츠 공과대학교', 2, 1, 1520, 1580, 'PLACEHOLDER', null, true, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (3, 'Harvard University', '하버드 대학교', 3, 1, 1500, 1580, 'PLACEHOLDER', null, true, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (4, 'Stanford University', '스탠퍼드 대학교', 4, 1, 1500, 1570, 'PLACEHOLDER', null, false, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (5, 'Yale University', '예일 대학교', 5, 1, 1500, 1560, 'PLACEHOLDER', null, true, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (6, 'University of Michigan, Ann Arbor', '미시간 대학교 앤아버', 21, 2, 1350, 1530, 'PLACEHOLDER', null, false, false, '{"cs","engineering"}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (7, 'Emory University', '에모리 대학교', 24, 2, 1420, 1540, 'PLACEHOLDER', null, false, true, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (8, 'New York University', '뉴욕 대학교', 30, 2, 1470, 1560, 'PLACEHOLDER', null, false, false, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (9, 'Boston University', '보스턴 대학교', 41, 3, 1360, 1500, 'PLACEHOLDER', null, false, true, '{}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url) values (10, 'University of Wisconsin-Madison', '위스콘신 대학교 매디슨', 39, 3, 1340, 1500, 'PLACEHOLDER', null, false, false, '{"engineering","business"}', 'PLACEHOLDER', 'PLACEHOLDER');
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (1, '4년 과목 플랜 짜기 — 수학 트랙부터 확인', '12학년까지 Calculus 도달 경로가 여기서 결정됨 — 학교 수학 시퀀스를 확인하고, 경로가 안 나오면 여름 보강 계획을 지금 세울 것', 9, 'fall', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (2, 'GPA 루틴 만들기', '9학년 성적도 GPA에 그대로 들어감 — 과제·시험 준비 루틴은 첫 학기에 잡는 게 가장 쉽고, 상승 곡선의 시작점이 됨', 9, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (3, '성격이 다른 활동 2~3개 시도', '지금은 잘하는 것보다 계속하고 싶은 걸 찾는 시기 — 만들기형·사람형·쓰기형처럼 유형을 다르게 골라볼 것', 9, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (4, '학교의 국제 인증(WASC·Cognia 등)과 school profile 존재 확인', '성적표의 대외 신뢰도를 좌우하는 정보 — 학교 행정실에 직접 물어보고, 없다면 AP·SAT 등 외부 지표 비중을 높이는 전략으로', 9, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (5, '영어 노출량 늘리기 (시험 말고 기반)', 'TOEFL은 아직 멀었음 — 지금은 관심 분야의 영어 콘텐츠를 일상으로 소비하는 습관이 나중의 점수를 만듦', 9, 'fall', null, null, true, false, 'testing', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (6, '10학년 과목 신청 — Honors 도전 포함', '리거는 학년마다 한 계단씩 올라가는 그림이 이상적 — 감당 가능한 선에서 Honors를 1~2개 넣을 것', 9, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (7, '시도한 활동 거르기 — 계속할 것만 남기기', '전부 유지하면 전부 얕아짐 — "다음 학기에도 하고 싶은가"로 판단해 2개 이내로', 9, 'spring', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (8, '여름 계획 세우기', '9학년 여름은 부담 없는 탐색이 정답 — 무료·자기주도 활동 하나면 충분하고, 비싼 캠프가 필요한 시기가 아님', 9, 'spring', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (9, '첫해 성적 점검 — 약한 과목 보강 계획', 'AO는 추세를 봄 — 9학년에 흔들린 과목은 10학년 상승으로 덮을 수 있으니 지금 원인을 찾을 것', 9, 'spring', null, null, false, false, 'rigor', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (10, '관심 분야 탐색 활동 1개 실행', '결과물이 없어도 됨 — "이 분야가 나랑 맞는지" 확인이 이번 여름의 목표', 9, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (11, '관심 분야 독서·기록 습관', '읽고 남긴 기록이 나중에 에세이 재료가 됨 — 짧은 감상이라도 남길 것', 9, 'summer', null, null, false, false, 'story', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (12, 'PSAT 연습 응시', '점수가 아니라 형식 경험이 목적 — 실전 감각은 한 번의 경험으로 크게 달라짐', 10, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (13, '첫 AP/Honors 과목 안착', '어려워진 과목에서 성적을 지키는 게 이번 학기 최우선 — 리거 상승과 GPA 유지를 동시에 잡는 연습', 10, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (14, '활동 몰입 시작 — 넓히는 시기는 끝', '이제부터는 남긴 활동을 깊게 파는 구간 — 새 활동 추가는 기존 것과 연결될 때만', 10, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (15, '추천서 후보 교사와 수업 안에서 신뢰 쌓기', '추천서는 벼락치기가 안 됨 — 11학년에 부탁할 교사 후보를 정하고 질문·참여로 기억에 남는 학생이 될 것', 10, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (16, '11학년 AP 라인업 확정', 'AP는 전년도에 신청함 — 전공 관련 핵심 AP가 포함됐는지, 미개설이면 자습 응시 계획까지 이번 달에 결정', 10, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (17, 'AP 시험 응시 (수강 중이라면)', '첫 AP 점수는 실전 리허설 — 5점이면 좋지만 시험 운영 경험 자체가 11학년 다과목 시즌의 자산', 10, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (18, 'SAT 공부 시작 시점 결정', '표준 리듬은 10학년 여름 시작 → 11학년 가을 1차 응시 — 목표 티어가 높을수록 이 리듬을 지킬 것', 10, 'spring', null, null, false, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (19, '여름 심화 활동 확정', '10학년 여름은 스파이크 만들기의 마지노선 — 프로젝트·리서치·봉사 중 하나를 구체적 계획으로', 10, 'spring', null, null, false, false, 'spike', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (20, '심화 활동 착수', '참가가 아니라 만들기 — 여름이 끝날 때 "보여줄 수 있는 것"이 하나 남는 걸 목표로', 10, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (21, 'SAT 기초 학습 시작', '진단 모의고사로 시작점 확인 → 약점 영역 중심 학습 — 무료 공식 자료(Khan Academy)로 충분한 단계', 10, 'summer', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (22, 'TOEFL 필요 여부 판단', '목표 학교마다 면제 기준이 다름 — 국제학교 재학 연수로 면제되는 학교도 있으니 목표 리스트 기준으로 확인 후 계획', 10, 'summer', null, null, true, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (23, 'PSAT 실전 응시', '11학년 PSAT는 실전 — SAT 직전 리허설이자 현재 위치 확인', 11, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (24, 'SAT 1차 응시 등록·응시', '가을 1차 → 봄 재응시가 표준 — 1차를 미루면 재응시 기회가 사라짐, 응시 장소는 미리 확보', 11, 'fall', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (25, 'AP 다과목 관리 루틴 세우기', '11학년은 최대 하중의 해 — 과목별 주간 루틴 없이는 전 과목이 같이 흔들림', 11, 'fall', null, null, false, false, 'rigor', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (26, '리더십 포지션 확보 또는 직접 만들기', 'AO는 직함보다 만든 것을 봄 — 기존 클럽 임원이 어려우면 작게라도 직접 만들 것', 11, 'fall', null, null, false, false, 'leadership', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (27, '외부 검증 도전 — 대회·투고 마감 확인', '원서에 들어갈 수확의 마지막 해 — 지금 마감 캘린더를 만들어야 봄의 기회를 놓치지 않음', 11, 'fall', null, null, false, false, 'validation', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (28, '추천서 교사 2명 내정', '12학년 가을에 부탁하면 늦음 — 지금부터 그 수업에서 추천서에 쓸 재료(질문·프로젝트·성장)를 만들 것', 11, 'fall', null, null, false, true, 'story', false, 60);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (29, 'SAT 재응시·마무리', '봄 안에 끝내는 게 목표 — 여름·가을은 에세이와 원서의 시간', 11, 'spring', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (30, 'AP 시험 시즌 운영', '다과목 시험은 체력전 — 과목별 우선순위를 정하고 전공 관련 과목에 5점을 집중', 11, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (31, '대학 리스트 초안 만들기', 'reach/match/safety 균형이 핵심 — 툴의 둘러보기와 내 위치 마커로 각 그룹 3~4개씩', 11, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (32, 'TOEFL 마무리', 'SAT와 원서가 몰리기 전에 끝낼 것 — 여름 이후로 밀리면 일정이 겹침', 11, 'spring', null, null, true, false, 'testing', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (33, '추천서 공식 부탁', '학년이 끝나기 전 부탁이 예의이자 안전 — 교사가 여름에 쓸 시간을 확보해주는 것', 11, 'spring', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (34, '원서 메인 에세이 초안 완성', '12학년 가을엔 쓸 시간이 없음 — 여름 초안, 가을 퇴고가 표준 리듬', 11, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (35, '대표 활동 마무리·정리', '스파이크를 "보여줄 수 있는 형태"로 — 결과물·숫자·기록을 지금 정리해야 활동란이 쉬워짐', 11, 'summer', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (36, '대학 리스트 확정 + ED/EA 전략 결정', 'ED는 합격 시 등록 의무가 있는 카드 — 진짜 1지망과 재정 조건을 함께 고려해 결정', 11, 'summer', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (37, '재정 서류 준비 논의 시작', '은행잔고증명 등은 부모님과 시간이 필요한 서류 — need-aware 학교 지원 전략과도 연결되니 여름에 논의 시작', 11, 'summer', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (38, 'Common App 계정 생성·활동란 초안', '활동란 10칸은 생각보다 오래 걸림 — 각 활동을 150자로 압축하는 연습을 지금', 11, 'summer', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (39, 'ED/EA 원서 제출 — 마감 역산 관리', '마감일이 아니라 발송 완료일 기준으로 역산 — 추천서·성적표는 내가 아니라 남이 보내는 것이므로 여유가 필수', 12, 'fall', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (40, '메인 에세이 완성 + 보충 에세이 착수', '보충 에세이가 진짜 분량 — 학교별 문항을 스프레드시트로 정리하면 겹치는 주제를 재활용할 수 있음', 12, 'fall', null, null, false, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (41, '성적표·추천서 발송 확인 — 담당자 직접 지정', '전담 카운슬러가 없으면 발송 주체가 불분명해짐 — 누가 언제 보내는지 이름과 날짜로 확정할 것', 12, 'fall', null, null, false, true, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (42, 'CSS Profile·재정증명 제출', '재정지원 서류는 원서와 마감이 다름 — 학교별 요구 서류와 마감을 따로 관리', 12, 'fall', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (43, '12학년 성적 유지', '합격 취소 사유 1위가 성적 급락 — 원서 시즌에도 수업은 평가되고 있음', 12, 'fall', null, null, false, false, 'rigor', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (44, 'RD 결과 정리·비교표 만들기', '감정이 아니라 조건으로 비교 — 학비·재정지원·전공 조건을 한 표에 놓고 볼 것', 12, 'spring', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (45, '재정지원 오퍼 검토·이의신청 확인', '오퍼는 협상 여지가 있는 경우가 있음 — 다른 학교 오퍼가 근거가 되기도 함', 12, 'spring', null, null, true, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (46, '최종 선택·디파짓', '등록 의사 마감일 확인 — 복수 디파짓은 원칙 위반이니 하나만', 12, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (47, 'I-20 신청·비자 인터뷰 준비', '합격 확정 즉시 시작 — 여름엔 인터뷰가 몰려서 늦으면 출국 일정이 위험해짐', 12, 'spring', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (48, '웨이트리스트 대응 (해당 시)', '관심 유지 편지(LOCI)는 새로운 업데이트가 있을 때만 효과 — 형식적 편지는 무의미', 12, 'spring', null, null, false, false, 'story', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (49, '입학 준비 — 기숙사·오리엔테이션·수강신청', '입학처 이메일이 여름 내내 옴 — 놓치면 불이익이 실제로 있으니 주 1회 메일 점검 루틴', 12, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (50, '최종 성적표 발송 확인', '발송 주체를 지정하고 도착까지 확인 — 이게 마지막 서류', 12, 'summer', null, null, false, true, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (51, '활동·툴 인수인계', '만든 것이 남으면 그게 legacy — 후배에게 자료·계정·노하우를 넘기고 기록으로 남길 것', 12, 'summer', null, null, false, false, 'leadership', true, 30);
